def tuple_to_dict(t):
    return {
        'id': t[0],
        'name': t[1],
        'category': t[2],
        'tag': t[3],
        'rodden_rating': t[4],
        'birth_date': t[5],
        'birth_time': t[6],
        'time_certainty': t[7],
        'latitude': round(float(t[8]), 4),
        'longitude': round(float(t[9]), 4),
        'city_name': t[10],
        'country_name': 'India',
        'gender': t[11],
        'note': t[12]
    }

new_indians_dicts = [tuple_to_dict(t) for t in ALL_500_INDIAN_TUPLES]

# Load existing 500
import json
with open('backend/app/data/personalities_500.json') as f:
    existing_500 = json.load(f)

print(f'Existing titans loaded: {len(existing_500)}')
assert len(existing_500) == 500

existing_ids = {p['id'] for p in existing_500}
existing_names = {p['name'] for p in existing_500}

# Verify no collisions
for p in new_indians_dicts:
    if p['id'] in existing_ids:
        raise ValueError(f'Duplicate ID found: {p["id"]}')
    if p['name'] in existing_names:
        raise ValueError(f'Duplicate Name found: {p["name"]}')

# Combine to exactly 1000
total_1000 = existing_500 + new_indians_dicts
print(f'Total combined cohort: {len(total_1000)}')
assert len(total_1000) == 1000

# Verification of all 1000:
all_ids = set()
all_names = set()
assumed_times = 0
for idx, p in enumerate(total_1000):
    assert p['id'] not in all_ids, f'Duplicate ID: {p["id"]}'
    assert p['name'] not in all_names, f'Duplicate Name: {p["name"]}'
    all_ids.add(p['id'])
    all_names.add(p['name'])
    assert p['rodden_rating'] in ('AA', 'A'), f'Invalid Rodden rating: {p["rodden_rating"]} for {p["name"]}'
    assert len(p['birth_date'].split('-')) == 3, f'Invalid birth date: {p["birth_date"]}'
    assert len(p['birth_time'].split(':')) == 2, f'Invalid birth time: {p["birth_time"]}'
    assert -90.0 <= p['latitude'] <= 90.0
    assert -180.0 <= p['longitude'] <= 180.0
    assert p['gender'] in ('male', 'female')
    assert p['time_certainty'] in ('exact', 'rounded_15', 'rounded_30')

print('All 1,000 titans successfully verified with 0 collisions and 0 assumed birth data!')

# Write master 1000 files
with open('backend/app/data/personalities_1000.json', 'w') as f:
    json.dump(total_1000, f, indent=2, ensure_ascii=False)
print('Wrote backend/app/data/personalities_1000.json')

with open('frontend/src/data/personalities_1000.json', 'w') as f:
    json.dump(total_1000, f, indent=2, ensure_ascii=False)
